import{_ as t,c as r,o as e,af as n,ap as o,aq as i}from"./chunks/framework.CI8A52oi.js";const g=JSON.parse('{"title":"什么是Java什么是基岩","description":"","frontmatter":{},"headers":[],"relativePath":"diffmc.md","filePath":"diffmc.md"}'),s={name:"diffmc.md"};function c(p,a,f,_,l,m){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="什么是java什么是基岩" tabindex="-1"><strong>什么是Java什么是基岩</strong> <a class="header-anchor" href="#什么是java什么是基岩" aria-label="Permalink to “什么是Java什么是基岩”">​</a></h1><h2 id="minecraft账户-版本常识" tabindex="-1"><strong>Minecraft账户/版本常识</strong> <a class="header-anchor" href="#minecraft账户-版本常识" aria-label="Permalink to “Minecraft账户/版本常识”">​</a></h2><p>在选择启动器之前,首先我们要了解一些Minecraft账户/版本常识,以免发生认知偏差.</p><p>如果你是一个新手玩家(或者没有了解过此类内容的老玩家),可能会认为Minecraft分为网易版,基岩版,教育版,手机版,电脑版等等乱七八糟的版本</p><p>实际上,Minecraft(这里指正作,不包括地下城等衍生游戏)只有两个版本,即<strong>Java版</strong>和<strong>基岩版</strong>.</p><p>基本上<strong>所有在手机上</strong>的Minecraft版本都是<strong>基岩版</strong>(包括网易代理的Minecraft手机版)</p><p>此外,教育版,360版,Win10版等版本也是基岩版(或基于基岩版开发)</p><p><img src="'+o+'" alt="基岩版"></p><blockquote><p>图为基岩版启动界面</p></blockquote><p>Java版则是<strong>基于Java运行的Minecraft版本</strong>,也是Minecraft的原生版本.你可以在Mac,Windows或Linux,甚至是任何一台装载Java且支持OpenGL的设备上运行.**大部分在电脑上运行的Minecraft都是Java版 **(Win10版等除外,那是基岩版).</p><p><em>实际上大多数MC主播或up主主要玩的都是java版，因为java版有比较稳定的特性（？）且生态更好</em></p><p><img src="'+i+'" alt="Java版"></p><blockquote><p>图为Java版启动界面</p></blockquote><p>手机通过<strong>特制启动器</strong>也可以运行Java版Minecraft(如PojavLuncher等)</p>',14)])])}const v=t(s,[["render",c]]);export{g as __pageData,v as default};
